	SELECT PRODUCT_ID, NAME, BRAND, CATEGORY, INGREDIENT, COST, HIT, ELIKE, IMAGE, HEARTED, row_num FROM (
	SELECT P.PRODUCT_ID, P.NAME, P.BRAND, P.CATEGORY, P.INGREDIENT, P.COST, P.HIT, P.ELIKE, P.IMAGE,


				1 AS HEARTED,


				CASE WHEN PS.USER_ID IS NOT NULL THEN 1 ELSE 0 END AS HEARTED,


				0 AS HEARTED,


		ROW_NUMBER() OVER(ORDER BY P.ELIKE DESC, P.PRODUCT_ID DESC) AS row_num
	FROM PRODUCT P


			INNER JOIN PRODUCT_SAVE PS ON P.PRODUCT_ID = PS.PRODUCT_ID AND PS.USER_ID = #{id}



				LEFT JOIN PRODUCT_SAVE PS ON P.PRODUCT_ID = PS.PRODUCT_ID AND PS.USER_ID = #{id}





