	                    	AND P.NAME LIKE '%' || #{keyword} || '%'


	                    	AND P.BRAND LIKE '%' || #{keyword} || '%'


	                    	AND P.INGREDIENT LIKE '%' || #{keyword} || '%'




		) temp_table WHERE row_num BETWEEN #{begin} AND #{end}



